import * as cdk from 'aws-cdk-lib';
import { Construct } from 'constructs';
import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';

export class DynamoDBStack extends cdk.Stack {
  constructor(scope: Construct, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    // Define a DynamoDB table
    const table = new dynamodb.Table(this, 'PointsOfInterestTable', {
      tableName: 'PointsOfInterest',
      partitionKey: { name: 'id', type: dynamodb.AttributeType.STRING },
      removalPolicy: cdk.RemovalPolicy.DESTROY,
    });
  }
}

sdk.code:
import boto3

dynamodb = boto3.resource('dynamodb')

# Create a table
table = dynamodb.create_table(
    TableName='PointsOfInterest',
    KeySchema=[
        {'AttributeName': 'id', 'KeyType': 'HASH'}
    ],
    AttributeDefinitions=[
        {'AttributeName': 'id', 'AttributeType': 'S'}
    ],
    ProvisionedThroughput={'ReadCapacityUnits': 5, 'WriteCapacityUnits': 5}
)

# Wait until the table exists
table.meta.client.get_waiter('table_exists').wait(TableName='PointsOfInterest')

terraform.code:
resource "aws_dynamodb_table" "points_of_interest" {
  name           = "PointsOfInterest"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"
  attribute {
    name = "id"
    type = "S"
  }
}

